var data_kategori_json=[];
$(document).ready(function() {
    get_data_kategori();
});

function get_data_kategori(){ 
    $.ajax({
        url: base_url+'load_maps/kategori_bencana_json',
        type: 'get',
        data: {},
        contentType: false,
        cache: false,
        processData:false,
        dataType: "JSON",
        success: function(response){
            data_kategori_json = response;
        },
        error: function(){
            //alert('Gagal terhubung ke server');
        }
    });
    
    return;
}

function getControlHrmlContent() {
    return `<div id="controlbox" >
                <div id="boxcontainer" class="searchbox searchbox-shadow" >
                    <div class="searchbox-menu-container">
                        <button aria-label="Menu" id="searchbox-menubutton" class="searchbox-menubutton"></button> <span aria-hidden="true" style="display:none">Menu</span> </div><div><input id="searchboxinput" type="text" placeholder="Misal: Banjir" style="position: relative; max-width: 75% !important;"/></div><div class="searchbox-searchbutton-container"><button aria-label="search" id="searchbox-searchbutton" class="searchbox-searchbutton"></button> <span aria-hidden="true" style="display:none;">search</span> </div></div></div><div class="panel"> <div class="panel-header"> <div class="panel-header-container"> <span class="panel-header-title"></span> <button aria-label="Menu" id="panelbutton" class="panel-close-button"></button> </div></div><div class="panel-content"> </div></div>`
}

function generateHtmlContent(a) {
    for (var b = '<ul class="panel-list">', d = 0; d < a.Items.length; d++) { 
        var c = a.Items[d],
            b = b + '<li class="panel-list-item"><div>';
        "link" == c.type ? (b += '<span class="panel-list-item-icon ' + c.icon + '" ></span>', b += '<a href="' + c.href + '">' + c.name + "</a>") : "button" == c.type && (b += '<span class="panel-list-item-icon ' + c.icon + '" ></span>', b += '<button onclick="' + c.onclick + '" id="'+ c.id +'">' + c.name + "</button>");
        b += "</li></div>"
    }
    return b + "</ul>"
}

function createSearchboxControl() {
    return L.Control.extend({
        _sideBarHeaderTitle: "Kategori",
        _sideBarMenuItems: {
            Items: [{
                type: "button",
                name: "Longsor",
                onclick: "refresh_map('kategori','longsor')",
                id: 'longsor'
                /*href: "http://github.com",
                icon: "icon-local-carwash"*/
            }, {
                type: "button",
                name: "Kebakaran",
                onclick: "refresh_map('kategori','kebakaran')",
                id: 'kebakaran'
            }, {
                type: "button",
                name: "Angin Puting Beliung",
                onclick: "refresh_map('kategori','angin puting beliung')",
                id: 'angin-puting-beliung'
            }, {
                type: "button",
                name: "Banjir",
                onclick: "refresh_map('kategori','banjir')",
                id: 'banjir'
            }, {
                type: "button",
                name: "Lainnya",
                onclick: "refresh_map('kategori','lainnya')",
                id: 'lainnya'
            }],
            _searchfunctionCallBack: function (a) {
                alert("calling the default search call back")
            }
        },
        options: {
            position: "topleft"
        },
        initialize: function (a) {
            L.Util.setOptions(this, a);
            a.sidebarTitleText && (this._sideBarHeaderTitle = a.sidebarTitleText);
            a.sidebarMenuItems && (this._sideBarMenuItems = a.sidebarMenuItems)
        },
        onAdd: function (a) {
            a = L.DomUtil.create("div");
            a.id = "controlcontainer";
            var b = this._sideBarHeaderTitle,
                d = this._sideBarMenuItems,
                c = this._searchfunctionCallBack;
            $(a).html(getControlHrmlContent());
            setTimeout(function () {
                $("#searchbox-searchbutton").click(function () {
                    var a = $("#searchboxinput").val();
                    c(a)
                });
                $("#searchbox-menubutton").click(function () {
                    $(".panel").toggle("slide", {
                        direction: "left"
                    }, 500)
                });
                $(".panel-close-button").click(function () {
                    $(".panel").toggle("slide", {
                        direction: "left"
                    }, 500)
                });
                $(".panel-header-title").text(b);
                var a = generateHtmlContent(d);
                $(".panel-content").html(a)
            }, 1);
            L.DomEvent.disableClickPropagation(a);
            return a
        }
    })
};
